local function fillGaps(seq)
	local kfs = seq.Keyframes
	local names = {}
	for _, kf in ipairs(kfs) do
		for name in pairs(kf.Poses) do names[name] = true end
	end
	for name in pairs(names) do
		for i, kf in ipairs(kfs) do
			if not kf.Poses[name] then
				local p, n
				for j = i - 1, 1, -1 do if kfs[j].Poses[name] then p = kfs[j] break end end
				for j = i + 1, #kfs do if kfs[j].Poses[name] then n = kfs[j] break end end
				if p and n then
					local a = (kf.Time - p.Time) / math.max(n.Time - p.Time, 0.001)
					kf.Poses[name] = p.Poses[name]:Lerp(n.Poses[name], a)
				else
					kf.Poses[name] = (p or n).Poses[name]
				end
			end
		end
	end
end

for _, seq in pairs(data) do fillGaps(seq) end

